package com.cognia.api.adapter.out.persistence;
import jakarta.persistence.Entity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="sesion_evaluacion") public class DiagnosticSessionJpaEntity {
	@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="estudiante_id",nullable=false) private UUID studentId; @Column(name="tipo_evaluacion",nullable=false) private String type; @Column(name="asignatura_id",nullable=false) private UUID subjectId; @Column(name="concepto_id") private UUID conceptId; @Column(name="paso_ruta_id") private UUID pathStepId; @Column(name="intento_numero",nullable=false) private int attempt=1; @Column(name="estado",nullable=false) private String state; @Column(name="puntaje_obtenido") private Double score; @Column(name="fecha_finalizacion") private Instant closedAt; @Column(name="aprobada") private Boolean passed;
	protected DiagnosticSessionJpaEntity(){} public DiagnosticSessionJpaEntity(UUID student,UUID subject){studentId=student;subjectId=subject;type="DIAGNOSTICO";state="EN_PROGRESO";} public DiagnosticSessionJpaEntity(UUID student,UUID subject,UUID concept,UUID step,int attempt){studentId=student;subjectId=subject;conceptId=concept;pathStepId=step;this.attempt=attempt;type="EVALUACION_CORTA";state="EN_PROGRESO";} public UUID getId(){return id;} public UUID getStudentId(){return studentId;} public UUID getSubjectId(){return subjectId;} public UUID getConceptId(){return conceptId;} public UUID getPathStepId(){return pathStepId;} public int getAttempt(){return attempt;} public String getType(){return type;} public String getState(){return state;} public Double getScore(){return score;} public Boolean getPassed(){return passed;} public Instant getClosedAt(){return closedAt;} public void complete(double value,Instant at){state="COMPLETADA";score=value;closedAt=at;passed=null;} public void complete(double value,boolean approved,Instant at){state="COMPLETADA";score=value;closedAt=at;passed=approved;}
}
